    price: 240
  }
];

let seq = 1002;

export function nextBookingId(): string {
  seq += 1;
  return `bk-${seq}`;
}

export function findRoom(id: string): Room | undefined {
  return rooms.find((r) => r.id === id);
}

export function bookingsForRoom(roomId: string): Booking[] {
  return bookings.filter((b) => b.roomId === roomId);
}

import { describe, it, expect, beforeEach } from "vitest";
import { bookings } from "../src/store.js";
import { call } from "./http.js";

const initial = bookings.map((booking) => ({ ...booking }));

beforeEach(() => {
  bookings.splice(0, bookings.length, ...initial.map((booking) => ({ ...booking })));
});

describe("GET /rooms/:id/availability", () => {
  it("renvoie les creneaux libres d'une salle sur la journee UTC demandee", async () => {
    const result = await call("/rooms/salle-a/availability?date=2026-10-05");

    expect(result).toEqual({
      status: 200,
      body: {
        roomId: "salle-a",
        date: "2026-10-05",
        slots: [
          { startsAt: "2026-10-05T00:00:00Z", endsAt: "2026-10-05T09:00:00Z" },
          { startsAt: "2026-10-05T11:00:00Z", endsAt: "2026-10-06T00:00:00Z" }
        ]
      }
    });
  });

  it("recadre et fusionne les reservations qui chevauchent la journee", async () => {
    bookings.push(
      {
        id: "bk-test-1",
        roomId: "labo",
        who: "nuit",
        people: 4,
        startsAt: "2026-10-04T22:00:00Z",
        endsAt: "2026-10-05T02:00:00Z",
        price: 0
      },
      {
        id: "bk-test-2",
        roomId: "labo",
        who: "matin",
        people: 4,
        startsAt: "2026-10-05T02:00:00Z",
        endsAt: "2026-10-05T04:00:00Z",
        price: 0
      },
      {
        id: "bk-test-3",
        roomId: "labo",
        who: "soir",
        people: 4,
        startsAt: "2026-10-05T22:00:00Z",
        endsAt: "2026-10-06T02:00:00Z",
        price: 0
      }
    );

    const result = await call("/rooms/labo/availability?date=2026-10-05");

    expect(result).toEqual({
      status: 200,
      body: {
        roomId: "labo",
        date: "2026-10-05",
        slots: [
          { startsAt: "2026-10-05T04:00:00Z", endsAt: "2026-10-05T22:00:00Z" }
        ]
      }
    });
  });

  it("renvoie toute la journee libre quand la salle n'a pas de reservation ce jour-la", async () => {
    const result = await call("/rooms/salle-b/availability?date=2026-10-05");

    expect(result).toEqual({
      status: 200,
      body: {
        roomId: "salle-b",
        date: "2026-10-05",
        slots: [
          { startsAt: "2026-10-05T00:00:00Z", endsAt: "2026-10-06T00:00:00Z" }
        ]
      }
    });
  });

  it("refuse une date absente ou invalide", async () => {
    expect((await call("/rooms/salle-a/availability")).status).toBe(400);
    expect((await call("/rooms/salle-a/availability?date=2026-02-30")).status).toBe(400);
    expect((await call("/rooms/salle-a/availability?date=2026-10-05T00:00:00Z")).status).toBe(400);
  });

  it("renvoie 404 pour une salle inconnue", async () => {
    expect((await call("/rooms/cave/availability?date=2026-10-05")).status).toBe(404);
  });
});

import { Router } from "express";
import { rooms, findRoom, bookingsForRoom } from "../store.js";
import { availabilityForDay } from "../lib/availability.js";
import { ValidationError } from "../lib/validate.js";

export const roomsRouter = Router();

roomsRouter.get("/", (_req, res) => {
  res.json({ rooms });
});

roomsRouter.get("/:id/availability", (req, res) => {
  try {
    const room = findRoom(req.params.id);
    if (!room) {
      res.status(404).json({ error: "salle inconnue" });
      return;
    }

    const { date } = req.query;
    if (typeof date !== "string") {
      throw new ValidationError("date requise au format YYYY-MM-DD");
    }
    const dayStart = Date.parse(`${date}T00:00:00.000Z`);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date) ||
        Number.isNaN(dayStart) ||
        new Date(dayStart).toISOString().slice(0, 10) !== date) {
      throw new ValidationError("date invalide : date");
    }

    res.json({ roomId: room.id, date, slots: availabilityForDay(bookingsForRoom(room.id), date) });
  } catch (err) {
    if (err instanceof ValidationError) {
      res.status(err.status).json({ error: err.message });
      return;
    }
    throw err;
  }
});

roomsRouter.get("/:id", (req, res) => {
  const room = findRoom(req.params.id);
  if (!room) {
    res.status(404).json({ error: "salle inconnue" });
    return;
  }
  res.json({ room, bookings: bookingsForRoom(room.id) });
});

